def extract_page_map(pdf_path, chapters):
    reader = PdfReader(str(pdf_path))
    pages_text = [(page.extract_text() or '') for page in reader.pages]
    toc_pages = [i for i, text in enumerate(pages_text) if 'Table of Contents' in text]
    toc_end = max(toc_pages) if toc_pages else 4
    page_map = {}
    for start, end, label, title in PARTS:
        page_map[f'part-{start:02d}'] = None
    for ch in chapters:
        page_map[f'ch-{ch["num"]:02d}'] = None

    for ch in chapters:
        needle = ch['title']
        for i in range(toc_end + 1, len(pages_text)):
            if needle in pages_text[i]:
                page_map[f'ch-{ch["num"]:02d}'] = i + 1
                break
    for start, end, label, title in PARTS:
        page_map[f'part-{start:02d}'] = page_map.get(f'ch-{start:02d}')

    missing = [k for k, v in page_map.items() if v is None]
    if missing:
        raise ValueError(f'Missing page mappings: {missing[:10]}')
    return page_map, len(reader.pages)


